/**
 * PF2e Ability Item Importer Macro
 *
 * Target: Foundry VTT + PF2e.
 * Primary input: compact JSON payload generated by the pf2e-fvtt-statblock-author skill.
 * Convenience input: GLUniverse strict Markdown action blocks when the
 * gluniverse-pf2e-statsblock-import module is active.
 *
 * The macro creates or updates owned PF2e Action items on an NPC/Hazard actor.
 * It deliberately stores PF2e inline syntax (@Check, @Damage, @Template, etc.)
 * verbatim so the installed PF2e system performs enrichment at render time.
 */

(async () => {
  const GL_IMPORTER_ID = "gluniverse-pf2e-statsblock-import";
  const MACRO_VERSION = 1;

  if (!game.user?.isGM) {
    ui.notifications.error("PF2e Ability Item Importer: 需要 GM 权限。");
    return;
  }

  const actors = game.actors
    .filter((actor) => ["npc", "hazard"].includes(actor.type))
    .sort((a, b) => a.name.localeCompare(b.name));

  if (!actors.length) {
    ui.notifications.warn("PF2e Ability Item Importer: 世界中没有 NPC 或 Hazard Actor。");
    return;
  }

  const controlled = canvas?.tokens?.controlled ?? [];
  const defaultActor = controlled.length === 1 && ["npc", "hazard"].includes(controlled[0].actor?.type)
    ? controlled[0].actor
    : actors[0];

  const actorOptions = actors
    .map((actor) => `<option value="${escapeHtml(actor.id)}" ${actor.id === defaultActor?.id ? "selected" : ""}>${escapeHtml(actor.name)}</option>`)
    .join("");

  const sample = JSON.stringify({
    version: MACRO_VERSION,
    items: [
      {
        name: "熵灾示例 Entropic Omen",
        actionType: "action",
        actions: 2,
        category: "offensive",
        traits: ["divine", "void"],
        frequency: "1 per round",
        description: "对@Template[type:cone|distance:30]范围内所有生物造成@Damage[6d6[void]|options:area-damage]伤害（@Check[fortitude|dc:32|basic|options:area-effect,inflicts:frightened]豁免）。失败获得惊惧 Frightened 1。"
      }
    ]
  }, null, 2);

  const content = `
    <div class="pf2e-ability-item-importer" style="display:grid;gap:0.75rem;min-width:620px">
      <label style="display:grid;gap:0.25rem">
        <strong>目标 Actor</strong>
        <select name="actorId">${actorOptions}</select>
      </label>
      <label style="display:grid;gap:0.25rem">
        <strong>能力数据</strong>
        <textarea name="source" rows="20" spellcheck="false" style="font-family:monospace;resize:vertical">${escapeHtml(sample)}</textarea>
      </label>
      <label style="display:flex;align-items:center;gap:0.4rem">
        <input type="checkbox" name="replaceExisting" checked>
        <span>同名 Action Item 存在时更新，而不是重复创建</span>
      </label>
      <p style="margin:0;opacity:.8">支持本技能生成的 JSON；若已启用 GLUniverse PF2e Stat Block Importer，也可粘贴 strict Markdown 的 Actions/Reactions/Passives 能力块。</p>
    </div>`;

  const formData = await promptInput(content);
  if (!formData) return;

  const values = formDataToObject(formData);
  const actor = game.actors.get(String(values.actorId ?? ""));
  if (!actor || !["npc", "hazard"].includes(actor.type)) {
    ui.notifications.error("PF2e Ability Item Importer: 未找到有效的目标 NPC/Hazard Actor。");
    return;
  }

  const source = String(values.source ?? "").trim();
  if (!source) {
    ui.notifications.warn("PF2e Ability Item Importer: 没有可导入的数据。");
    return;
  }

  let abilities;
  try {
    abilities = sourceLooksJson(source)
      ? parseJsonPayload(source)
      : parseViaGlUniverse(source, GL_IMPORTER_ID);
  } catch (error) {
    console.error("PF2e Ability Item Importer parse error", error);
    ui.notifications.error(`PF2e Ability Item Importer: ${error.message ?? error}`);
    return;
  }

  if (!abilities.length) {
    ui.notifications.warn("PF2e Ability Item Importer: 没有解析到 Action/Reaction/Passive 能力。");
    return;
  }

  const sources = abilities.map((ability) => buildActionItemSource(ability));
  const replaceExisting = values.replaceExisting === true || values.replaceExisting === "on" || values.replaceExisting === "true";

  const updates = [];
  const creates = [];
  for (const itemSource of sources) {
    const existing = replaceExisting
      ? actor.items.find((item) => item.type === "action" && normalizeName(item.name) === normalizeName(itemSource.name))
      : null;
    if (existing) updates.push({ _id: existing.id, ...itemSource });
    else creates.push(itemSource);
  }

  try {
    if (updates.length) await actor.updateEmbeddedDocuments("Item", updates);
    if (creates.length) await actor.createEmbeddedDocuments("Item", creates);
  } catch (error) {
    console.error("PF2e Ability Item Importer create/update error", error);
    ui.notifications.error(`PF2e Ability Item Importer: 创建物品失败：${error.message ?? error}`);
    return;
  }

  ui.notifications.info(`PF2e Ability Item Importer: ${actor.name} 已更新 ${updates.length} 个、创建 ${creates.length} 个能力物品。`);

  function sourceLooksJson(text) {
    const first = text.trimStart()[0];
    return first === "{" || first === "[";
  }

  function parseJsonPayload(text) {
    const payload = JSON.parse(text);
    const rawItems = Array.isArray(payload) ? payload : payload.items;
    if (!Array.isArray(rawItems)) throw new Error("JSON 必须是数组，或包含 items 数组。");
    if (payload?.version != null && Number(payload.version) > MACRO_VERSION) {
      throw new Error(`载荷版本 ${payload.version} 高于宏支持的版本 ${MACRO_VERSION}。`);
    }
    return rawItems.map(normalizeAbilityPayload);
  }

  function normalizeAbilityPayload(raw, index) {
    if (!raw || typeof raw !== "object") throw new Error(`items[${index}] 不是对象。`);
    const name = String(raw.name ?? "").trim();
    if (!name) throw new Error(`items[${index}] 缺少 name。`);

    const actionType = normalizeActionType(raw.actionType ?? raw.type ?? "action");
    const actionCount = actionType === "action" ? clampInt(raw.actions ?? 1, 1, 3) : null;
    const traits = Array.isArray(raw.traits)
      ? raw.traits.map(slugify).filter(Boolean)
      : splitList(raw.traits).map(slugify).filter(Boolean);

    return {
      name,
      actionType,
      actions: actionCount,
      category: slugify(raw.category ?? "offensive") || "offensive",
      traits,
      frequency: raw.frequency ?? "",
      description: String(raw.description ?? ""),
      rules: Array.isArray(raw.rules) ? raw.rules : [],
      img: typeof raw.img === "string" && raw.img.trim() ? raw.img.trim() : null
    };
  }

  function parseViaGlUniverse(text, moduleId) {
    const api = game.modules.get(moduleId)?.api;
    if (!api?.parse) {
      throw new Error("当前输入不是 JSON，且未检测到已启用的 GLUniverse PF2e Stat Block Importer API。请改用 JSON 载荷，或启用该模块。");
    }

    const wrapped = ensureStrictStatblock(text);
    const parsed = api.parse(wrapped);
    if (!parsed?.npc) throw new Error("GLUniverse importer 未返回可用的 NPC 解析结果。");
    if (parsed.errors?.length) throw new Error(`GLUniverse 解析失败：${parsed.errors.join("；")}`);

    return (parsed.npc.actions ?? []).map((action) => ({
      name: action.name,
      actionType: normalizeActionType(action.actionType),
      actions: normalizeActionType(action.actionType) === "action" ? clampInt(action.actions ?? 1, 1, 3) : null,
      category: action.category || "offensive",
      traits: action.traits ?? [],
      frequency: action.frequency ?? "",
      description: action.description ?? "",
      rules: action.rules ?? [],
      img: null
    }));
  }

  function ensureStrictStatblock(text) {
    if (/^\s*#\s+\S/m.test(text)) return text;
    const body = /^\s*##\s+/m.test(text) ? text.trim() : `## Actions\n\n${text.trim()}`;
    return [
      "# Macro Scratch Actor",
      "Level: 1",
      "Rarity: common",
      "Size: medium",
      "Traits: construct",
      "Perception: +0",
      "Abilities: STR +0, DEX +0, CON +0, INT +0, WIS +0, CHA +0",
      "AC: 10",
      "Fortitude: +0",
      "Reflex: +0",
      "Will: +0",
      "HP: 1",
      "Speed: 25 feet",
      "",
      body
    ].join("\n");
  }

  function buildActionItemSource(ability) {
    const actionType = normalizeActionType(ability.actionType);
    const actions = actionType === "action" ? clampInt(ability.actions ?? 1, 1, 3) : null;
    const system = {
      description: { value: descriptionToHtml(ability.description), gm: "" },
      rules: structuredCloneSafe(ability.rules ?? []),
      slug: slugify(ability.name),
      traits: { value: ability.traits ?? [], otherTags: [] },
      actionType: { value: actionType },
      actions: { value: actions },
      category: ability.category || "offensive"
    };

    const frequency = normalizeFrequency(ability.frequency);
    if (frequency) system.frequency = frequency;

    return {
      name: ability.name,
      type: "action",
      img: ability.img || actionIcon(actionType, actions),
      system
    };
  }

  function descriptionToHtml(text) {
    const normalized = String(text ?? "")
      .replace(/\r\n?/g, "\n")
      .replace(/\\r\\n/g, "\n")
      .replace(/\\n/g, "\n");
    const withConditions = linkConditionsUsingLivePf2e(normalized);
    return withConditions
      .split(/\n{2,}/)
      .map((paragraph) => `<p>${escapeHtml(paragraph.trim()).replace(/\n/g, "<br>")}</p>`)
      .join("\n");
  }

  function linkConditionsUsingLivePf2e(text) {
    const manager = game.pf2e?.ConditionManager;
    const slugs = Array.isArray(manager?.conditionsSlugs) ? [...manager.conditionsSlugs] : [];
    if (!slugs.length) return text;

    let output = text;
    for (const slug of slugs.sort((a, b) => b.length - a.length)) {
      let condition;
      try {
        condition = manager.getCondition(slug);
      } catch (_error) {
        continue;
      }
      const uuid = condition?._stats?.compendiumSource ?? condition?.uuid;
      if (!uuid) continue;

      const englishLabel = slug
        .split("-")
        .map((part) => part ? part[0].toUpperCase() + part.slice(1) : part)
        .join("-");
      const pattern = new RegExp(`\\b${escapeRegExp(englishLabel)}\\b`, "g");
      output = output.replace(pattern, (match, offset, full) => {
        const prefix = full.slice(Math.max(0, offset - 160), offset);
        // Skill-generated directives use lowercase slugs. This guard mainly prevents
        // re-linking a condition already present in an explicit UUID directive.
        if (prefix.lastIndexOf("@UUID[") > prefix.lastIndexOf("]")) return match;
        return `@UUID[${uuid}]{${match}}`;
      });
    }
    return output;
  }

  function normalizeFrequency(value) {
    if (!value) return null;
    if (typeof value === "object") {
      const max = Number(value.max ?? value.value ?? 1);
      const per = String(value.per ?? "day");
      return { max, value: Number(value.value ?? max), per };
    }
    const text = String(value).trim();
    const max = Number(text.match(/\d+/)?.[0] ?? 1);
    const per = text.match(/per\s+(round|minute|hour|day)/i)?.[1]?.toLowerCase()
      ?? text.match(/\/(round|minute|hour|day)/i)?.[1]?.toLowerCase()
      ?? "day";
    return { max, value: max, per };
  }

  function normalizeActionType(value) {
    const slug = slugify(value);
    if (slug.includes("reaction")) return "reaction";
    if (slug.includes("free")) return "free";
    if (slug.includes("passive")) return "passive";
    return "action";
  }

  function actionIcon(type, actions) {
    if (type === "reaction") return "systems/pf2e/icons/actions/Reaction.webp";
    if (type === "free") return "systems/pf2e/icons/actions/FreeAction.webp";
    if (type === "passive") return "systems/pf2e/icons/actions/Passive.webp";
    return `systems/pf2e/icons/actions/${actions ?? 1}Action.webp`;
  }

  function structuredCloneSafe(value) {
    if (globalThis.structuredClone) return structuredClone(value);
    return JSON.parse(JSON.stringify(value));
  }

  function splitList(value) {
    return String(value ?? "").split(/,|;/).map((part) => part.trim()).filter(Boolean);
  }

  function slugify(value) {
    return String(value ?? "")
      .trim()
      .toLowerCase()
      .replace(/['’]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
  }

  function normalizeName(value) {
    return String(value ?? "").trim().toLocaleLowerCase();
  }

  function clampInt(value, min, max) {
    const number = Number.parseInt(value, 10);
    return Math.min(max, Math.max(min, Number.isFinite(number) ? number : min));
  }

  function escapeRegExp(value) {
    return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function escapeHtml(value) {
    return String(value ?? "").replace(/[&<>\"]/g, (character) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;"
    })[character]);
  }

  function formDataToObject(formData) {
    if (!formData) return {};
    if (formData.object && typeof formData.object === "object") return formData.object;
    if (typeof formData.entries === "function") return Object.fromEntries(formData.entries());
    return formData;
  }

  async function promptInput(dialogContent) {
    const DialogV2 = foundry?.applications?.api?.DialogV2;
    if (DialogV2?.input) {
      return DialogV2.input({
        window: { title: "PF2e Ability Item Importer" },
        content: dialogContent,
        rejectClose: false,
        modal: true,
        ok: { label: "导入能力" }
      });
    }

    if (globalThis.Dialog) {
      return new Promise((resolve) => {
        new Dialog({
          title: "PF2e Ability Item Importer",
          content: `<form>${dialogContent}</form>`,
          buttons: {
            import: {
              label: "导入能力",
              callback: (html) => {
                const root = html?.[0] ?? html;
                const form = root?.querySelector?.("form") ?? root;
                resolve(form ? new FormData(form) : null);
              }
            },
            cancel: { label: "取消", callback: () => resolve(null) }
          },
          default: "import",
          close: () => resolve(null)
        }).render(true);
      });
    }

    throw new Error("当前 Foundry 版本没有可用的 DialogV2 或 legacy Dialog API。");
  }
})();
